INSERT INTO `Templates` VALUES ('0848cabd-2e31-4cff-a908-a7eef428ef08','Html.RowInvoiceDetail','<tr><td style=\"border: 1px solid #000; padding: 6px; text-align: center;\">@electricityMeterName</td><td style=\"border: 1px solid #000; padding: 6px; text-align: center;\">@transfomerStationName</td><td style=\"border: 1px solid #000; padding: 6px; text-align: center;\">@endNum</td><td style=\"border: 1px solid #000; padding: 6px; text-align: center;\">@startNum</td><td style=\"border: 1px solid #000; padding: 6px; text-align: center;\">@electricityConsumption</td><td style=\"border: 1px solid #000; padding: 6px; text-align: right;\">@totalAmount</td></tr>','2026-04-06 01:05:40.324313','00000000-0000-0000-0000-000000000000','2026-04-06 01:05:40.307600','00000000-0000-0000-0000-000000000000'),('69b65fb9-6cc7-414a-9b99-eb2c509c0f06','Html.Invoice','<div style=\'border: 2px solid #000; padding: 20px;\'>\n\n<h1 style=\'text-align: center; margin-bottom: 5px;\'>\nBIÊN NHẬN THANH TOÁN TIỀN ĐIỆN\n</h1>\n\n<div style=\'text-align: center; font-weight: bold;\'>\nTên trạm biến áp T295E(ĐD471ELH)\n</div>\n\n<div style=\'text-align: center;\'>\nTháng: @month\n</div>\n\n<div style=\'margin-top: 10px;\'>\n<span style=\'font-weight: bold;\'>Tên khách hàng:</span> @customerName<br>\n<span style=\'font-weight: bold;\'>Số điện thoại:</span> @customerPhone<br>\n</div>\n\n<div style=\'margin-top: 10px; font-weight: bold;\'>\nChủ Đầu Tư: @projectOwner\n</div>\n\n<div style=\'margin-top: 10px;\'>\n<span style=\'font-weight: bold;\'>Stk nhận thanh toán:</span>\n@bankAccountNumber - @bankName - @accountHolderName\n</div>\n\n<div style=\'margin-top: 10px; font-weight: bold;\'>\nGiá Điện: @unitPrice đồng/kWh\n</div>\n\n<table style=\'width: 100%; border-collapse: collapse; margin-top: 15px;\'>\n<thead>\n<tr>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Tên ĐH</th>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Trạm</th>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Số Mới</th>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Số Cũ</th>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Điện Năng TT</th>\n<th style=\'border: 1px solid #000; padding: 6px;\'>Thành Tiền</th>\n</tr>\n</thead>\n<tbody>\n@invoiceDetails\n<tr>\n<td colspan=\'5\' style=\'border: 1px solid #000; padding: 6px; font-weight: bold; text-align: left;\'>\nTổng số tiền thanh toán\n</td>\n<td style=\'border: 1px solid #000; padding: 6px; font-weight: bold; text-align: right;\'>\n@totalAmount\n</td>\n</tr>\n</tbody>\n</table>\n\n<div style=\'margin-top: 20px;\'>\n<span style=\'font-weight: bold;\'>Số tiền bằng chữ:</span>\n@wordOfTotalAmount\n</div>\n\n<div style=\'margin-top: 10px;\'>\nLưu ý: biên nhận này là xác thực khách hàng đã thanh toán tiền điện.\nnếu cần liên hệ dịch vụ điện Quý khách vui lòng gọi số: @customerServicePhone\n</div>\n\n<div style=\'margin-top: 20px; text-align: right;\'>\n<span style=\'font-weight: bold;\'>Nhân Viên Thu Tiền:</span> @cashierName\n</div>\n\n</div>','2026-04-06 01:06:58.622913','00000000-0000-0000-0000-000000000000','2026-04-06 01:06:58.610011','00000000-0000-0000-0000-000000000000'),('89be3b0e-f1e1-43bc-93f4-f93aecf69eff','Html.BreakPage','<p style=\"break-after: page;\">&nbsp;</p>','2026-04-06 01:16:40.722792','00000000-0000-0000-0000-000000000000','2026-04-06 01:18:39.561241','00000000-0000-0000-0000-000000000000'),('fdd7b0e1-701f-4772-b666-42ed8b4e99c4','Html.Wrapper','<!DOCTYPE html><html lang=\"vi\"><head><meta charset=\"UTF-8\"><title></title></head><body style=\"font-family: \'Times New Roman\', serif; margin: 20px;\">@body</body></html>','2026-04-06 00:58:16.208400','00000000-0000-0000-0000-000000000000','2026-04-06 00:58:16.088707','00000000-0000-0000-0000-000000000000');
